This uses dynamic programming to find palindromic substrings and the minimum cuts for each prefix. Time: O(n²). Space: O(n²). Call solve(s) with a nonempty string; it returns the minimum cuts without any input/output handling.

```javascript
function solve(s) {
  const n = s.length;
  const palindrome = Array.from(
    { length: n }, () => new Uint8Array(n)
  );
  const cuts = new Array(n);

  for (let end = 0; end < n; end++) {
    cuts[end] = end;

    for (let start = 0; start <= end; start++) {
      if (
        s[start] === s[end] &&
        (end - start <= 1 || palindrome[start + 1][end - 1])
      ) {
        palindrome[start][end] = 1;
        cuts[end] = Math.min(
          cuts[end],
          start === 0 ? 0 : cuts[start - 1] + 1
        );
      }
    }
  }

  return cuts[n - 1];
}
```

