Use topological layers: start with cells having no larger orthogonal neighbor, then remove them and unlock smaller neighbors. The number of layers equals the longest strictly increasing path length, without risking recursive stack overflow. Time: O(rows × columns); space: O(rows × columns).

Call solve(matrix) directly; no input/output handling is needed.

```javascript
function solve(matrix) {
  const rows = matrix.length;
  if (rows === 0 || matrix[0].length === 0) return 0;
  const cols = matrix[0].length;
  const degree = new Array(rows * cols).fill(0);
  const queue = [];
  const directions = [[1, 0], [-1, 0], [0, 1], [0, -1]];

  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      const id = r * cols + c;
      for (const [dr, dc] of directions) {
        const nr = r + dr;
        const nc = c + dc;
        if (
          nr >= 0 && nr < rows && nc >= 0 && nc < cols &&
          matrix[nr][nc] > matrix[r][c]
        ) {
          degree[id]++;
        }
      }
      if (degree[id] === 0) queue.push(id);
    }
  }

  let head = 0;
  let length = 0;
  while (head < queue.length) {
    const layerEnd = queue.length;
    length++;
    while (head < layerEnd) {
      const id = queue[head++];
      const r = Math.floor(id / cols);
      const c = id % cols;

      for (const [dr, dc] of directions) {
        const nr = r + dr;
        const nc = c + dc;
        if (
          nr >= 0 && nr < rows && nc >= 0 && nc < cols &&
          matrix[nr][nc] < matrix[r][c]
        ) {
          const neighbor = nr * cols + nc;
          degree[neighbor]--;
          if (degree[neighbor] === 0) queue.push(neighbor);
        }
      }
    }
  }

  return length;
}
```

