Use modified merge sort: count pairs within each half, count cross-half pairs before merging, then merge the sorted halves. Time: O(n log n); auxiliary space: O(n). Call solve(nums) directly; the input is not modified.

```javascript
function solve(nums) {
  const a = nums.slice();
  const buffer = new Array(a.length);

  function sortAndCount(lo, hi) {
    if (hi - lo <= 1) return 0;

    const mid = lo + Math.floor((hi - lo) / 2);
    let count = sortAndCount(lo, mid) + sortAndCount(mid, hi);

    let j = mid;
    for (let i = lo; i < mid; i++) {
      while (j < hi && a[i] > 2 * a[j]) j++;
      count += j - mid;
    }

    let left = lo;
    let right = mid;
    let write = lo;

    while (left < mid && right < hi) {
      if (a[left] <= a[right]) {
        buffer[write++] = a[left++];
      } else {
        buffer[write++] = a[right++];
      }
    }
    while (left < mid) buffer[write++] = a[left++];
    while (right < hi) buffer[write++] = a[right++];

    for (let i = lo; i < hi; i++) a[i] = buffer[i];
    return count;
  }

  return sortAndCount(0, a.length);
}
```

